class Basis(StrEnum):
    fixed = 'fixed'
    estimated_units = 'estimated_units'
    cpm_deferred = 'cpm_deferred'


class ConsumptionEstimate(Consumption):
    pass


class PerLeafItem(AdCPBaseModel):
    model_config = ConfigDict(
        extra='allow',
    )
    catalog_item_ref: dict[str, Any] | None = None
    variant_axis_value: Any | None = None
    pricing_option_id: str | None = None
    cost_low: Annotated[float | None, Field(ge=0.0)] = None
    cost_high: Annotated[float | None, Field(ge=0.0)] = None
    consumption_estimate: Annotated[
        ConsumptionEstimate | None,
        Field(
            description='Structured consumption details returned by build_creative when a paid creative agent computes cost. Contains well-known fields for common consumption metrics. The consumption object is informational — it lets the buyer verify that vendor_cost is consistent with the rate card. vendor_cost is the billing source of truth, not consumption.',
            title='Creative Consumption',
        ),
    ] = None


class Estimate(AdCPBaseModel):
    model_config = ConfigDict(
        extra='allow',
    )
    items_total: Annotated[
        int | None,
        Field(description='Catalog items eligible (before max_creatives sampling).', ge=0),
    ] = None
    items_to_produce: Annotated[
        int | None,
        Field(description='Distinct creatives that would be produced (after max_creatives).', ge=0),
    ] = None
    conditions_total: Annotated[
        int | None,
        Field(
            description='Signal-fan-out conditions axis count (len(signal_conditions)). Present when signal_conditions was sent so leaves_total = items_to_produce × conditions_total × variants_per_item is legible before spend.',
            ge=1,
        ),
    ] = None
    variants_per_item: Annotated[
        int | None, Field(description='Alternatives per creative (max_variants).', ge=1)
    ] = None
    leaves_total: Annotated[
        int | None,
        Field(description='Total billable leaves = items_to_produce × variants_per_item.', ge=0),
    ] = None
    currency: Annotated[
        str, Field(description='ISO 4217 currency for the cost band.', pattern='^[A-Z]{3}$')
    ]
    cost_low: Annotated[
        float, Field(description='Low end of the projected aggregate vendor_cost.', ge=0.0)
    ]
    cost_high: Annotated[
        float,
        Field(description='High end. For basis "fixed" this equals cost_low (exact).', ge=0.0),
    ]
    cost_expected: Annotated[
        float | None, Field(description='Optional point estimate within the band.', ge=0.0)
    ] = None
    basis: Annotated[
        Basis,
        Field(
            description='`fixed` = per-format flat pricing (cost_low == cost_high, exact). `estimated_units` = generative per_unit where the seller projects a unit range (band reflects the uncertainty in seconds/images/tokens). `cpm_deferred` = CPM-priced; build-time cost is 0 and cost accrues at serve time (mirrors the vendor_cost:0 CPM convention).'
        ),
    ]
    per_leaf: Annotated[
        list[PerLeafItem] | None, Field(description='Optional per-leaf breakdown of the estimate.')
    ] = None


